                got[name[4:]]=hashlib.sha256(tf.extractfile(m).read()).hexdigest()
    assert got==expected,app+' archive mismatch'
    assert any(url in p.read_bytes() for p in original.rglob('*.js')),app+' missing API URL'
    checkout=root/'.sites'/('deploy05-save-'+app)
    for folder in ['apps/customer','apps/customer-service','packages','scripts/sites']:
        files=subprocess.check_output(['git','ls-tree','-r','--name-only','4b6a4aa','--',folder],text=True).splitlines()
        for file in files:
            if '/.openai/' in file:continue
            assert (checkout/file).read_bytes()==subprocess.check_output(['git','show','4b6a4aa:'+file]),file
    print(app+': archive matches all '+str(len(got))+' built files; API URL present; source matches 4b6a4aa.')
